package hu.bankmonitor.payments.transfers.checks;

/**
 * A condition a Transfer must satisfy before it can settle, answered by a party outside
 * this context.
 *
 * <p>A human approver and an automated service are the same kind of thing here: each
 * answers one of these constants for one Transfer, through the same operation. That
 * indistinguishability is what the asynchronous lifecycle was chosen for — a new condition
 * is a constant here and a line in {@link CheckPolicy}, not a new mechanism.
 *
 * <p>The constants are stored by name, so they are part of the schema: {@code
 * V4__check_ledger.sql} lists them in a check constraint, and renaming one is a migration
 * rather than a refactor.
 */
public enum Check {

	/** Automated fraud screening, answered by a service the outbox pushes the request to. */
	FRAUD,

	/** A person signing off in a back-office tool, reporting through the same endpoint. */
	MANUAL_APPROVAL
}
package hu.bankmonitor.payments.transfers.checks;

/**
 * A {@link Check}'s answer for one Transfer.
 *
 * <p>There are two answers and there is no third. A Check that has not answered has no
 * Verdict at all, which the ledger records as an absent column rather than as a constant
 * here — {@link CheckLedgerEntry} has the argument for that, and it is a claim about the
 * domain: "not yet answered" is the absence of an answer, not one of the answers.
 *
 * <p>The two are not symmetrical in what they cost. {@link #APPROVED} advances nothing on
 * its own — it is the other rows that decide — while {@link #REJECTED} ends the Transfer
 * whatever the rest of the ledger says. {@link LedgerDecision} is where that asymmetry is
 * written down.
 */
public enum Verdict {

	/** This Check is satisfied. The Transfer settles once every other Check agrees. */
	APPROVED,

	/** This Check says no, and that is the whole answer: the Transfer is rejected. */
	REJECTED
}
package hu.bankmonitor.payments.transfers.checks;

import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.type.SqlTypes;

import java.util.Objects;

/**
 * One Check a Transfer requires, and how that Check has answered it.
 *
 * <p>A Transfer's rows together are its Check Ledger, and they are written when the
 * Transfer is: the set of rows is fixed at request time, not a log that grows as parties
 * report things. The unique constraint on {@code (transfer_id, required_check)}
 * says the same in the table, and it is what will make a Check service's at-least-once
 * delivery safe to receive.
 *
 * <p><b>An unanswered Check has no Verdict, and the column is null.</b> The alternative —
 * a third {@code PENDING} constant on {@link Verdict}, which is the shape design decision
 * 8 sketched — would make "nobody has answered" one of the answers, and every reader would
 * then have to know which of the three is not really a Verdict. {@link
 * hu.bankmonitor.payments.transfers.TransferStatus} carries {@code PENDING} for the
 * opposite reason: a Transfer really is in that state. Nothing is in the state of having
 * given the null answer.
 *
 * <p><b>The Transfer is referenced by ID, not by association</b>, on {@code Transfer}'s own
 * precedent: a Transfer only ever leaves {@code PENDING} by a conditional update guarded on
 * the status it is leaving, and an association would offer a second way to reach one that
 * quietly skips that.
 *
 * <p><b>The identifier is surrogate rather than the pair that is unique</b>, on {@code
 * IdempotencyRecord}'s precedent: Spring Data decides between insert and merge from whether
 * the identifier is set, so an assigned key would turn every {@code save} into a
 * {@code SELECT} followed by an {@code UPDATE}. The uniqueness that matters is a named
 * constraint either way.
 *
 * <p>There is deliberately no mutator. Ticket 20 writes a Verdict as an update guarded on
 * the row still being unanswered, because two deliveries of the same Verdict have to leave
 * the Transfer advanced once; a setter would offer a second way to make that transition
 * that quietly is not atomic.
 */
@Entity
@Table(name = "check_ledger")
class CheckLedgerEntry {

	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	private Long id;

	private Long transferId;

	// `check` is reserved in SQL, so the column this name produces is `required_check`.
	@Enumerated(EnumType.STRING)
	@JdbcTypeCode(SqlTypes.VARCHAR)
	private Check requiredCheck;

	// If left unannotated, JPA stores the verdict by ordinal. See design decision 29.
	@Enumerated(EnumType.STRING)
	@JdbcTypeCode(SqlTypes.VARCHAR)
	private Verdict verdict;

	protected CheckLedgerEntry() {
		// required by JPA
	}

	/**
	 * A row in any state it can hold, which is what {@link LedgerDecision#decide} is
	 * specified over and therefore has to be able to see.
	 *
	 * <p>Production never reaches this with a Verdict in hand — {@link #outstanding} is how
	 * a row comes into being, and the answer arrives later as an update. That is the
	 * distinction being drawn: constructing a row in a state is not the same operation as
	 * <em>transitioning</em> one into it, and only the transition has a race to lose.
	 */
	CheckLedgerEntry(Long transferId, Check requiredCheck, Verdict verdict) {
		this.transferId = Objects.requireNonNull(transferId, "a check is required of a transfer");
		this.requiredCheck = Objects.requireNonNull(requiredCheck, "a ledger row is one check");
		this.verdict = verdict;
	}

	/** Opens a Check on a Transfer with nobody having answered it yet. */
	static CheckLedgerEntry outstanding(Long transferId, Check requiredCheck) {
		return new CheckLedgerEntry(transferId, requiredCheck, null);
	}

	Long getId() {
		return id;
	}

	/**
	 * Whether this row is the one the given Check answers.
	 *
	 * <p>What it is for is telling the two causes of a guarded update matching nothing apart:
	 * the Check was already answered, or the Transfer never required it. Only the second is a
	 * caller naming something that does not exist.
	 */
	boolean isFor(Check check) {
		return requiredCheck == check;
	}

	/** Whether this Check has said no — the one answer that ends a Transfer on its own. */
	boolean isRejected() {
		return verdict == Verdict.REJECTED;
	}

	/** Whether anyone has answered this Check at all, either way. */
	boolean isAnswered() {
		return verdict != null;
	}
}
package hu.bankmonitor.payments.transfers.checks;

import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.Repository;

import java.util.List;

/**
 * Persistence for {@link CheckLedgerEntry}, package-private so that reaching it from
 * another slice does not compile (design decision 30).
 *
 * <p>The bare {@link Repository} marker rather than {@code JpaRepository}, on {@code
 * Account}'s precedent: it declares nothing, so every method here is one with a call site
 * today. The two ticket 20 brought — the read that a Verdict's decision is made over, and
 * the update guarded on the row still being unanswered — are below.
 */
interface CheckLedgerRepository extends Repository<CheckLedgerEntry, Long> {

	/** Opens one Check on one Transfer, which is how a ledger row comes to exist. */
	CheckLedgerEntry save(CheckLedgerEntry entry);

	/** One Transfer's whole Check Ledger, which is what {@link LedgerDecision#decide} reads. */
	List<CheckLedgerEntry> findAllByTransferId(Long transferId);

	/**
	 * Writes a Verdict into the one row that is still outstanding for that Check, and
	 * reports how many rows that was — one, or none because somebody has already answered.
	 *
	 * <p><b>{@code verdict is null} is the guard, and it is what makes a Check service's
	 * at-least-once delivery safe.</b> A second delivery of the same Verdict matches no row
	 * and writes nothing, so the ledger keeps the answer it already had; a contradicting one
	 * cannot overwrite it either. A read-then-write would be the same rule with a window in
	 * the middle where both deliveries see the row unanswered.
	 *
	 * <p>A bulk update rather than a mutator on the entity, on {@code IdempotencyRecord}'s
	 * precedent: a setter would offer a second way to make this transition that quietly is
	 * not atomic. {@link CheckLedgerEntry} therefore has none.
	 */
	@Modifying
	@Query("""
			UPDATE CheckLedgerEntry entry SET entry.verdict = :verdict
			WHERE entry.transferId = :transferId
			  AND entry.requiredCheck = :check
			  AND entry.verdict IS NULL
			""")
	int answer(Long transferId, Check check, Verdict verdict);
}
package hu.bankmonitor.payments.transfers.checks;

import hu.bankmonitor.payments.transfers.Transfer;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Objects;
import java.util.Set;

/**
 * The per-Transfer record of which Checks it requires and how each has been answered, and
 * the two operations this package exports: opening that record, and answering one Check in
 * it.
 *
 * <p>The two are the ledger's whole life and they are deliberately the only ways into it.
 * Every row a Transfer will ever have is written by {@link #openFor}, and the only thing
 * that happens to one afterwards is {@link #record} filling in its Verdict — there is no way
 * to add a row, remove one, or answer the same Check twice, which is what lets
 * {@link LedgerDecision#decide} read the rows as the whole truth about the Transfer.
 *
 * <p>The whole of what the Check Ledger is for rests on it being written <em>with</em> the
 * Transfer. A Transfer whose rows were written afterwards has a window in which it is
 * {@code PENDING} against an empty ledger — which is a Transfer nothing will ever settle,
 * expire or explain, holding an operator's funds until somebody notices. {@link
 * Propagation#MANDATORY} is that requirement stated to the container rather than left as a
 * convention for the caller to honour: this method cannot start a transaction of its own,
 * so the only way to call it is from inside one that is already writing the Transfer.
 *
 * <p>Being late is one way to that state and requiring nothing is the other: a policy that
 * names no Check makes {@link #openFor} write no rows and return, so the caller commits the
 * same stuck Transfer with every test still green. The refusal below is that second way
 * closed, at the only place that can see it happening.
 *
 * <p>The method is public on a package-private-by-default design because {@code
 * @Transactional} on a non-public method is silently ignored under proxy-based AOP — the
 * trap {@link hu.bankmonitor.payments} documents. The class is public for the ordinary
 * reason: {@code FundsReservation} is in the parent package and has to name it.
 */
@Component
public class CheckLedger {

	private final CheckPolicy policy;

	private final CheckLedgerRepository entries;

	CheckLedger(CheckPolicy policy, CheckLedgerRepository entries) {
		this.policy = policy;
		this.entries = entries;
	}

	/**
	 * Writes one outstanding row per Check the Transfer requires, in the caller's
	 * transaction.
	 *
	 * @param transfer a Transfer already written, so that the rows have an ID to point at
	 * @throws org.springframework.transaction.IllegalTransactionStateException if the caller
	 *                                                                         has no
	 *                                                                         transaction
	 *                                                                         open
	 * @throws IllegalStateException if the policy requires no Checks at all, which would
	 *                               write no rows and leave the caller committing the stuck
	 *                               Transfer described above
	 */
	@Transactional(propagation = Propagation.MANDATORY)
	public void openFor(Transfer transfer) {
		Long transferId = Objects.requireNonNull(transfer.getId(), "a ledger belongs to a written transfer");

		Set<Check> required = policy.requiredFor(transfer);
		if (required.isEmpty()) {
			throw new IllegalStateException("a transfer's check ledger is never empty");
		}

		for (Check check : required) {
			entries.save(CheckLedgerEntry.outstanding(transferId, check));
		}
	}

	/**
	 * Answers one outstanding Check and says what the whole ledger then supports, in the
	 * caller's transaction.
	 *
	 * <p>The answer is written by {@linkplain CheckLedgerRepository#answer a guarded update}
	 * rather than a read followed by a write, so two deliveries of the same Verdict leave one
	 * answer. A second delivery matching no row is not a refusal: nothing went wrong on the
	 * reporting side, and the caller still needs the decision back, because the delivery that
	 * did win may have been lost on the way home. What it does mean is that the decision here
	 * is made over what the ledger <em>holds</em>, never over the Verdict just handed in.
	 *
	 * <p><b>The rows are read after the update, and nothing may have read them before it.</b>
	 * A bulk update goes straight to the database and leaves the persistence context alone,
	 * so an entry loaded earlier in the same transaction would come back from
	 * {@link CheckLedgerRepository#findAllByTransferId} still carrying its old, unanswered
	 * Verdict — and a ledger whose last outstanding row looks outstanding decides {@code
	 * WAIT}, leaving a fully approved Transfer pending for ever. This is the only method that
	 * reads the rows, and it reads them here.
	 *
	 * <p>{@link Propagation#MANDATORY} for {@link #openFor}'s reason turned around: the
	 * decision returned here is acted on by moving money, and an answer committed separately
	 * from the movement it authorises is either a settled Transfer nobody paid or a payment
	 * against a ledger that does not record why.
	 *
	 * @return what the Transfer's ledger now supports, which the caller owns acting on
	 * @throws org.springframework.transaction.IllegalTransactionStateException if the caller
	 *                                                                         has no
	 *                                                                         transaction
	 *                                                                         open
	 * @throws CheckNotRequiredException if the Transfer's ledger has no row for that Check,
	 *                                   which is also the answer a Transfer with no ledger at
	 *                                   all gets — it reaches this refusal before
	 *                                   {@link LedgerDecision#decide} can be handed the empty
	 *                                   rows it exists to refuse
	 */
	@Transactional(propagation = Propagation.MANDATORY)
	public LedgerDecision record(long transferId, Check check, Verdict verdict) {
		int answered = entries.answer(transferId, check, verdict);
		List<CheckLedgerEntry> ledger = entries.findAllByTransferId(transferId);

		if (answered == 0 && ledger.stream().noneMatch(entry -> entry.isFor(check))) {
			throw new CheckNotRequiredException(transferId, check);
		}
		return LedgerDecision.decide(ledger);
	}
}

